pub(crate) fn is_id_start(c: char) -> bool {
	if c.is_ascii() {
		return c.is_ascii_alphabetic() || c == '$' || c == '_';
	}
	ID_START.contains(c as u32)
}

pub(crate) fn is_id_continue(c: char) -> bool {
	if c.is_ascii() {
		return c.is_ascii_alphanumeric() || c == '$' || c == '_';
	}
	ID_CONTINUE.contains(c as u32)
}

#[cfg(test)]
mod tests {
	use super::*;

	#[test]
	#[rustfmt::skip]
	fn every_level_answers() {
		for (c, start, cont) in [
			('a', true, true), ('1', false, true), ('$', true, true), ('-', false, false),
			('\u{aa}', true, true), ('\u{b7}', false, true), ('\u{d7}', false, false),
			('\u{2c1}', true, true), ('\u{300}', false, true), ('\u{37e}', false, false),
			('\u{4e00}', true, true), ('\u{200c}', false, true), ('\u{fffd}', false, false),
			('\u{10000}', true, true), ('\u{1d4b3}', true, true), ('\u{1f600}', false, false),
			('\u{e0100}', false, true), ('\u{10ffff}', false, false),
		] {
			assert_eq!(is_id_start(c), start, "start of {c:?}");
			assert_eq!(is_id_continue(c), cont, "continue of {c:?}");
		}
	}
}
